&3 x \cos \left(\frac{\pi}{2}-\theta\right)+2 y \cot \left(\frac{\pi}{2}-\theta\right)=3^2+2^2 \\
&\Rightarrow 3 h \sin \theta+2 k \tan \theta=3^2+2^2
